  (142, 'pricing_tiers', 2, '"3"', '价格档次数量（1-5）', '', 100, 1, '2026-08-12 10:39:17', '2026-08-12 10:39:17', NULL),
  (143, 'pricing_1_title', 2, '"商业授权版本"', '档次一：名称', '', 100, 1, '2026-08-12 10:39:17', '2026-08-12 10:39:17', NULL),
  (144, 'pricing_1_price', 2, '"¥9,999"', '档次一：价格', '', 100, 1, '2026-08-12 10:39:17', '2026-08-12 10:39:17', NULL),
  (145, 'pricing_1_desc', 2, '"适合中小型知识付费平台，基础功能齐全，快速上线运营"', '档次一：简介', '', 100, 1, '2026-08-12 10:39:17', '2026-08-12 10:39:17', NULL),
  (146, 'pricing_1_features', 2, '"全形态内容付费\\n直播互动带货\\n多商户店铺经营\\nAI 智能客服\\n可视化装修\\n基础技术支持"', '档次一：功能列表（每行一个）', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (147, 'pricing_2_title', 2, '"企业版本"', '档次二：名称', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (148, 'pricing_2_price', 2, '"¥29,999"', '档次二：价格', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (149, 'pricing_2_desc', 2, '"适合中大型企业，全功能开放，专属部署与优先服务"', '档次二：简介', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (150, 'pricing_2_features', 2, '"商业授权全部功能\\n独立部署专属环境\\n数据大屏与深度分析\\n全渠道营销工具\\n一对一专属顾问\\n7×12 小时技术支持"', '档次二：功能列表（每行一个）', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (151, 'pricing_3_title', 2, '"二开定价咨询"', '档次三：名称', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (152, 'pricing_3_price', 2, '"定制报价"', '档次三：价格', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
  (153, 'pricing_3_desc', 2, '"根据业务场景深度定制，按需求评估方案与报价"', '档次三：简介', '', 100, 1, '2026-08-12 10:39:18', '2026-08-12 10:39:18', NULL),
